<?php
declare(strict_types=1);
use Nexus\Application\Inventario\InventarioService;use Nexus\Domain\Inventario\InventarioRepository;use Nexus\Domain\ValueObject\Cedula;
require_once __DIR__.'/../proyecto 3ra entrega/src/autoload.php';
final class InventarioMemoria implements InventarioRepository
{
    public array $ubicaciones=[1=>['nombre'=>'Laboratorio 1','activa'=>1],2=>['nombre'=>'Laboratorio 2','activa'=>1]];public array $equipos=[];public array $historial=[];
    public function listarEquipos():array{$r=[];foreach($this->equipos as $e)if($e['esta_activo']&&$e['estado_equipo']!=='Baja'){$e['seccion_inventario']=$this->ubicaciones[$e['id_ubicacion']]['nombre'];$r[]=$e;}return $r;}public function ubicacionExiste(int $id,bool $a=false):bool{return isset($this->ubicaciones[$id])&&(!$a||$this->ubicaciones[$id]['activa']);}
    private function evento(string $accion,Cedula $autor):void{$this->historial[]=['accion'=>$accion,'autor'=>$autor->value()];}
    public function crearEquipo(array $d,Cedula $a):int{$id=count($this->equipos)+1;$this->equipos[$id]=['id_equipo'=>$id,'nombre_equipo'=>$d['nombre'],'categoria_equipo'=>$d['tipo'],'descripcion'=>$d['observaciones'],'marca_equipo'=>$d['marca'],'cantidad_del_equipo'=>$d['cantidad'],'esta_activo'=>$d['activo'],'estado_equipo'=>$d['estadoBase'],'fecha_agregado'=>'2026-10-19','id_ubicacion'=>$d['seccionId']];$this->evento('Alta',$a);return $id;}public function editarEquipo(int $id,array $d,Cedula $a):bool{if(!isset($this->equipos[$id])||!$this->equipos[$id]['esta_activo'])return false;foreach(['nombre'=>'nombre_equipo','tipo'=>'categoria_equipo','observaciones'=>'descripcion','marca'=>'marca_equipo','cantidad'=>'cantidad_del_equipo','estado'=>'estado_equipo','seccionId'=>'id_ubicacion'] as $x=>$b)if(isset($d[$x]))$this->equipos[$id][$b]=$d[$x];$this->evento('Modificacion',$a);return true;}public function trasladarEquipo(int $id,int $destino,Cedula $a):?bool{if(!isset($this->equipos[$id]))return null;if($this->equipos[$id]['id_ubicacion']===$destino)return false;$this->equipos[$id]['id_ubicacion']=$destino;$this->evento('Traslado',$a);return true;}public function bajaEquipo(int $id,Cedula $a):?bool{if(!isset($this->equipos[$id]))return null;if(!$this->equipos[$id]['esta_activo'])return false;$this->equipos[$id]['esta_activo']=0;$this->equipos[$id]['estado_equipo']='Baja';$this->evento('Baja',$a);return true;}
    public function esquemaUbicacionesActualizado():bool{return true;}public function listarUbicaciones():array{$r=[];foreach($this->ubicaciones as $id=>$u)if($u['activa']){$cantidad=count(array_filter($this->equipos,fn($e)=>$e['id_ubicacion']===$id&&$e['esta_activo']));$r[]=['id_ubicacion'=>$id,'seccion_inventario'=>$u['nombre'],'cantidad_equipos'=>$cantidad];}return $r;}public function crearUbicacion(string $n,Cedula $a):int{$id=count($this->ubicaciones)+1;$this->ubicaciones[$id]=['nombre'=>$n,'activa'=>1];$this->evento('Alta seccion',$a);return $id;}public function renombrarUbicacion(int $id,string $n,Cedula $a):bool{if(!$this->ubicacionExiste($id,true))return false;$this->ubicaciones[$id]['nombre']=$n;$this->evento('Modificacion seccion',$a);return true;}public function bajaUbicacion(int $id,?int $destino,Cedula $a):?array{if(!isset($this->ubicaciones[$id]))return null;if(!$this->ubicaciones[$id]['activa'])return ['sinCambios'=>true,'cantidad'=>0];$ids=array_keys(array_filter($this->equipos,fn($e)=>$e['id_ubicacion']===$id&&$e['esta_activo']));if($ids&&$destino===null)throw new \Nexus\Shared\DomainException('Elegi una seccion destino para trasladar los equipos antes de eliminar.');foreach($ids as $e)$this->equipos[$e]['id_ubicacion']=$destino;$this->ubicaciones[$id]['activa']=0;$this->evento('Baja seccion',$a);return ['cantidad'=>count($ids),'destino'=>$destino];}
}
function assertInv(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}$r=new InventarioMemoria();$s=new InventarioService($r);$autor=new Cedula('57324099');$id=$s->altaEquipo(['nombre'=>'Notebook Dell Latitude','tipo'=>'Notebook','observaciones'=>'Equipo docente','marca'=>'Dell','cantidad'=>2,'seccionId'=>1,'estado'=>'Activo'],$autor);assertInv($id===1&&$r->historial[0]['accion']==='Alta'&&$r->historial[0]['autor']==='57324099','Alta sin autor en historial.');$s->editarEquipo(1,['nombre'=>'Notebook Dell Latitude 5420','tipo'=>'Notebook','observaciones'=>'Equipo docente','marca'=>'Dell','cantidad'=>2,'seccionId'=>1,'estado'=>'Mantenimiento'],$autor);assertInv($r->equipos[1]['estado_equipo']==='Mantenimiento','Edición incompleta.');$s->trasladarEquipo(1,2,$autor);assertInv($r->equipos[1]['id_ubicacion']===2,'Traslado falló.');$u=$s->altaUbicacion('Sala de reuniones',$autor);$s->renombrarUbicacion($u,'Sala de reuniones 1',$autor);assertInv($r->ubicaciones[$u]['nombre']==='Sala de reuniones 1','Renombrado falló.');$resultado=$s->bajaUbicacion(2,1,$autor);assertInv($resultado['equiposTrasladados']===1&&$r->equipos[1]['id_ubicacion']===1,'Baja no trasladó equipos.');$s->bajaEquipo(1,$autor);assertInv(!$r->equipos[1]['esta_activo']&&end($r->historial)['accion']==='Baja','Baja de equipo falló.');assertInv(count(array_filter($r->historial,fn($e)=>$e['autor']==='57324099'))===7,'No todos los cambios conservaron el autor.');echo "OK: 15 comportamientos de inventario e historial por autor verificados.\n";
